-- Extra vragenpool: vergroot de vijver zodat niet iedereen dezelfde test krijgt.
-- Idempotent: bestaande vragen met dezelfde NL-tekst worden overgeslagen.

INSERT INTO public.academy_vragen
  (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en,
   opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, 'tekst', v.nl, v.fr, v.en, v.onl::jsonb, v.ofr::jsonb, v.oen::jsonb, v.ci, v.wnl, v.wfr, v.wen
FROM (VALUES

-- ============================ KIP ============================
('kip',1,'Hoeveel ruimte heeft een kip minstens nodig in een ren?','De combien d''espace une poule a-t-elle besoin au minimum dans un enclos ?','How much space does a hen need at minimum in a run?',
